var n=`0514-quzi`;var a=`world-0514`;var o=`IQ`;var t=`western-asia`;var r=4;var s=177;var l={en:`Quzi`,ua:`Кузі`};var d={en:`A traditional dish from Iraq, centered on lamb, yellow onion, basmati rice, raisin. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Ірак. Основні складники: ягнятина, жовта цибуля, рис басматі, родзинки. Домашній варіант із кількостями продуктів за етапами приготування.`};var g=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 15 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 15 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:15,i:[[`lamb`,950,`g`],[`yellow-onion`,240,`g`],[`extra-virgin-olive-oil`,70,`ml`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 130 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 130 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:130,i:[[`water`,1100,`ml`],[`ground-cardamom`,6,`g`],[`allspice-berries`,4,`g`]]},{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 27 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 27 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:27,i:[[`basmati-rice`,480,`g`],[`raisin`,90,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:5,i:[[`almond`,90,`g`]]}];var u={slug:n,id:a,country:`IQ`,region:t,servings:4,minutes:177,title:l,text:d,steps:g};export{o as country,u as default,a as id,s as minutes,t as region,r as servings,n as slug,g as steps,d as text,l as title};